'use strict';
const $=id=>document.getElementById(id),KEY='omni.darkreader.v1';
const defaults={version:1,global:false,sites:{},mode:'dynamic',brightness:100,contrast:100,sepia:0};
let state={...defaults,sites:{}},adapter,ps=true;
let settingsReady=false,saveError='';
try{const raw=localStorage.getItem(KEY);if(raw!==null){const saved=JSON.parse(raw);if(!saved||saved.version!==1||typeof saved!=='object'||Array.isArray(saved))throw Error('Unsupported saved preferences');const next={...defaults,...saved,sites:{...(saved.sites||{})}};if(typeof next.global!=='boolean'||!['dynamic','filter','cache'].includes(next.mode)||!Object.entries({brightness:[50,150],contrast:[50,150],sepia:[0,100]}).every(([k,[min,max]])=>Number.isFinite(next[k])&&next[k]>=min&&next[k]<=max)||saved.sites&&(!saved.sites||typeof saved.sites!=='object'||Array.isArray(saved.sites))||Object.values(next.sites).some(v=>typeof v!=='boolean'))throw Error('Invalid saved preferences');state=next;}settingsReady=true;}catch{saveError='Saved local preferences could not be read. Controls stay disabled; reload to try again.'}
delete state.shortcut;
const effective=()=>state.sites[$('site').value]??state.global;
const cacheKey=()=>`omni.dark.css.v1:${$('site').value}:fixture-v1:4.9.134:${state.brightness}:${state.contrast}:${state.sepia}`;
function persist(){if(!settingsReady)return false;try{localStorage.setItem(KEY,JSON.stringify(state));saveError='';return true}catch{saveError='Preview changed, but local preferences were not saved.';return false}}
function parity(){const query=$('settings-search').value.trim().toLowerCase();let count=0;for(const id of ['mode','brightness','contrast','sepia']){const row=$(id).closest('label');row.hidden=!row.textContent.toLowerCase().includes(query);if(!row.hidden)count++;} $('settings-empty').hidden=count>0;for(const id of ['quick','everywhere','siteToggle','reset','mode','brightness','contrast','sepia','cache','clearcache'])$(id).disabled=!settingsReady;$('reset-appearance').disabled=!settingsReady||!!query;$('settings-read').textContent=saveError||'Local preview preferences loaded. Native add-on settings are separate.';}
$('settings-search').oninput=parity;
$('reset-appearance').onclick=()=>{if($('reset-appearance').disabled)return;for(const k of ['mode','brightness','contrast','sepia'])state[k]=defaults[k];persist();apply();};
function render(){const on=effective();$('quick').textContent='Dark Reader · '+(on?'On':state.sites[$('site').value]===false?'Off for this site':'Off');$('quick').setAttribute('aria-pressed',String(on));$('siteToggle').textContent=(on?'Turn off':'Turn on')+' for this site';$('everywhere').textContent=state.global?'Turn off everywhere':'Turn on everywhere';$('everywhere').setAttribute('aria-pressed',String(state.global));$('mode').value=state.mode;for(const k of ['brightness','contrast','sepia']){$(k).value=state[k];$(k+'-value').textContent=state[k]+'%'}$('sites').replaceChildren();for(const [origin,enabled] of Object.entries(state.sites)){const li=document.createElement('li');li.textContent=origin+' · '+(enabled?'On':'Off');$('sites').append(li)}if(!$('sites').children.length){const li=document.createElement('li');li.textContent='No site overrides';$('sites').append(li)}}
function apply(){render();parity();if(!adapter)return;let css;try{const c=JSON.parse(localStorage.getItem(cacheKey()));if(c&&Date.now()-c.saved<86400000)css=c.css}catch{}const actual=adapter.apply({...state,enabled:effective()},css);$('status').textContent=actual==='off'?'Dark Reader is off.':actual==='cache'?'Saved style applied. Refresh it when the page changes.':actual==='filter'?'Lightweight filter applied.':'Dark Reader is on.'}
function changeSite(){state.sites[$('site').value]=!effective();persist();apply()}
$('quick').onclick=changeSite;$('siteToggle').onclick=changeSite;
$('everywhere').onclick=()=>{state.global=!state.global;state.sites={};persist();apply()};
$('reset').onclick=()=>{delete state.sites[$('site').value];persist();apply()};
$('site').onchange=apply;$('mode').onchange=()=>{state.mode=$('mode').value;persist();apply()};
for(const k of ['brightness','contrast','sepia'])$(k).oninput=()=>{state[k]=Number($(k).value);persist();apply()};

$('cache').onclick=async()=>{if(adapter?.mode!=='dynamic'){$('status').textContent='Turn on Dark mode before saving its style.';return}try{const css=await adapter.exportCSS();if(css.length>=1048576)throw Error('Style is too large to cache.');localStorage.setItem(cacheKey(),JSON.stringify({saved:Date.now(),css}));$('status').textContent='Style saved for the next visit.'}catch{$('status').textContent='The style could not be saved. Dynamic mode remains available.'}};
$('clearcache').onclick=()=>{try{for(const k of Object.keys(localStorage))if(k.startsWith('omni.dark.css.v1:'))localStorage.removeItem(k);$('status').textContent='Cached styles cleared.'}catch{$('status').textContent='Storage is unavailable.'}};
$('glyphs').onclick=()=>{ps=!ps;$('glyphs').textContent=ps?'PlayStation hints':'Xbox hints';$('hints').textContent=ps?'D-pad · Move / Cross · Select / Circle · Back':'D-pad · Move / A · Select / B · Back'};
$('load-preview').onclick=()=>{$('sample').hidden=false;$('sample').src='fixture.html';$('load-preview').disabled=true;};
$('sample').onload=()=>{if(typeof $('sample').contentWindow.createOmniDarkReader!=='function')return;adapter=$('sample').contentWindow.createOmniDarkReader($('sample').contentWindow);window.darkPreview=adapter;apply()};
window.omniPadController=window.omniMediaController=function(action){if(action==='darkReaderShortcut')return false;const focus=[...document.querySelectorAll('button,input,select,summary')].filter(x=>x.getClientRects().length&&!x.disabled);let i=focus.indexOf(document.activeElement);if(['up','down','left','right'].includes(action)){const a=document.activeElement;if(a?.type==='range'&&['left','right'].includes(action)){a.value=Number(a.value)+(action==='left'?-5:5);a.dispatchEvent(new Event('input'));return true}if(a?.tagName==='SELECT'&&['left','right'].includes(action)){a.selectedIndex=Math.max(0,Math.min(a.options.length-1,a.selectedIndex+(action==='left'?-1:1)));a.dispatchEvent(new Event('change'));return true}focus[(i+(action==='up'||action==='left'?-1:1)+focus.length)%focus.length]?.focus();return true}if(action==='confirm'){document.activeElement?.click();return true}if(action==='back'){const details=document.querySelector('details');if(details.open){details.open=false;details.querySelector('summary').focus();return true}return false}return false};
document.addEventListener('keydown',e=>{if(e.target.id==='settings-search'&&!['ArrowUp','ArrowDown','Escape'].includes(e.key))return;const action={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',Escape:'back'}[e.key];if(action&&window.omniPadController(action))e.preventDefault()});render();parity();
